<?php require 'config/db.php';$q=$pdo->prepare("SELECT * FROM events WHERE slug=? AND status='published' LIMIT 1");$q->execute([$_GET['slug']??'']);$ev=$q->fetch();if(!$ev){http_response_code(404);die('Event not found');}$page_title=$ev['title'];include 'includes/header.php';?><section class="page-hero"><div class="container"><span class="eyebrow"><?=date('d M Y',strtotime($ev['event_date']))?> · <?=e($ev['location'])?></span><h1><?=e($ev['title'])?></h1></div></section><section class="content-shell"><div class="container split"><div class="media-frame"><img src="<?=e($ev['image_url'])?>" alt="<?=e($ev['title'])?>"></div><div class="form-card"><p class="lead"><?=nl2br(e($ev['body']))?></p><a class="btn btn-primary" href="contact.php"><i class="fa-solid fa-calendar-check"></i> Enquire About Event</a></div></div></section><?php include 'includes/footer.php'; ?>